#include <IQM/hdrvdp3/srgb_quality96_runtime_double.h>
#include <vulkan_instance.h>
#include <fstream>
#include <iostream>
#include <bit>
#include <limits>
using namespace IQM::HDRVDP3;namespace fs=std::filesystem;
std::vector<double> readRow(const fs::path&p,unsigned w){std::ifstream f(p,std::ios::binary|std::ios::ate);if(!f||f.tellg()!=std::streamoff(w*w*8))throw std::runtime_error("Reference shape "+p.string());std::vector<double> v(w*w),row(w*w);f.seekg(0);f.read(reinterpret_cast<char*>(v.data()),v.size()*8);for(unsigned y=0;y<w;++y)for(unsigned x=0;x<w;++x)row[y*w+x]=v[x*w+y];return row;}
int main(int argc,char**argv){try{if(argc!=4)throw std::invalid_argument("Usage: v5-runtime cpu-root fresh-output");fs::path runtime=argv[1],cpu=argv[2],out=argv[3];if(fs::exists(out)||!fs::create_directories(out))throw std::invalid_argument("Fresh output");auto model=load_srgb_quality96_runtime_double(runtime,"oled");IQM::Bin::VulkanInstance instance(true,"NVIDIA",true);SRGBQuality96GPUDouble gpu(*instance.physicalDevice(),*instance.device(),*instance.queue(),instance.queueFamilyIndex,true,model.shaders,model.projection,model.mutual,model.neighbor,model.pyramid);size_t words=0;auto compare=[&](const std::vector<double>&a,const std::vector<double>&b,const std::string& name){if(a.size()!=b.size())throw std::runtime_error("Shape "+name);for(size_t i=0;i<a.size();++i)if(std::bit_cast<uint64_t>(a[i])!=std::bit_cast<uint64_t>(b[i]))throw std::runtime_error(name+" bits at "+std::to_string(i));words+=a.size();};const unsigned widths[]{96,96,48,24,12};
 for(std::string native:{"native","native_ramps","native_identity_v2"})for(std::string display:{"led-lcd-srgb","led-lcd-wcg","oled"})for(unsigned side=1;side<=2;++side){auto name=display+"_"+std::to_string(side),prefix=(cpu/native/name).string();auto input=readRow(prefix+"_P.f64",96);auto result=gpu.pyramid(input);auto save=[&](const std::string& field,const std::vector<double>& values){std::ofstream f(out/(native+"_"+name+"_"+field+".f64"),std::ios::binary);f.write(reinterpret_cast<const char*>(values.data()),values.size()*8);};for(unsigned b=0;b<5;++b){auto field="band"+std::to_string(b+1);compare(result.bands[b].values,readRow(prefix+"_"+field+".f64",widths[b]),field);save(field,result.bands[b].values);}compare(result.base_pre,readRow(prefix+"_base_pre.f64",12),"base_pre");compare({result.base_mean},readRow(prefix+"_base_mean.f64",1),"base_mean");save("base_pre",result.base_pre);save("base_mean",{result.base_mean});}
 size_t nativeWords=words;for(unsigned seed=0;seed<4;++seed){std::vector<double> input(9216);for(size_t i=0;i<input.size();++i)input[i]=seed==0?(i==0?1.:0.):seed==1?(i==48*96+48?1.:0.):seed==2?3.25:(i%2?-.013:.009)*double(i%97);auto actual=gpu.pyramid(input),expected=build_sp0_pyramid_double(input);for(unsigned b=0;b<5;++b)compare(actual.bands[b].values,expected.bands[b].values,"control band");compare(actual.base_pre,expected.base_pre,"control base_pre");compare({actual.base_mean},{expected.base_mean},"control mean");}
 unsigned rejected=0;auto reject=[&](auto action){try{action();}catch(const std::exception&){++rejected;return;}throw std::runtime_error("Invalid pyramid input accepted");};reject([&]{gpu.pyramid({});});std::vector<double> bad(9216,1.);for(double v:{std::numeric_limits<double>::quiet_NaN(),std::numeric_limits<double>::infinity()}){bad[0]=v;reject([&]{gpu.pyramid(bad);});}std::ofstream(out/"PASS.txt")<<nativeWords<<" native Double pyramid words exact;"<<words-nativeWords<<" control words exact;"<<rejected<<" rejection checks\n";std::cout<<words<<" pyramid words exact\n";return 0;
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
